<?php if(!$listRows):?><div class="empty"><div class="eyebrow">A fresh page</div><h2><?=$showNames?'No shared reflections this month':'No reflections here yet'?></h2><p><?=$showNames?'Only entries their authors explicitly make public appear here.':'When you are ready, start with one moment and one question.'?></p><a class="btn primary" href="?p=treatment">Start a reflection →</a></div><?php else:?><div class="table-scroll"><table><thead><tr><th scope="col">Reflection</th><?php if($showNames):?><th scope="col">Shared by</th><?php endif;?><th scope="col">Date & time</th><th scope="col">Intensity</th><th scope="col">Visibility</th><th scope="col"><span class="muted">Details</span></th></tr></thead><tbody><?php foreach($listRows as $r):?><tr data-log-row><td>#<?=e($r['id'])?></td><?php if($showNames):?><td><?=e(getName($r['username']))?></td><?php endif;?><td><?=e($r['timestamp'])?></td><td><?=e(str_replace('option','',(string)$r['angerScale']))?> / 10</td><td><span class="badge <?=(int)$r['public']===1?'public':''?>"><?=(int)$r['public']===1?'Public':'Private'?></span></td><td><a class="quiet" href="?p=viewLog&id=<?=e($r['id'])?>" aria-label="View reflection <?=e($r['id'])?>">View →</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>